fields.html:
{#- Standard valuation report, structure per CLAUDE.md §5.
    Wording is our own. Text that is legal in nature is marked PLACEHOLDER
    until approved wording exists (CLAUDE.md §11); a report must not be
    issued while any remains. -#}
{% macro placeholder(what) -%}
<p class="placeholder">[PLACEHOLDER – replace with approved wording: {{ what }}]</p>
{%- endmacro %}

{% macro table(rows, cls="kv") -%}
<table class="{{ cls }}">
  {% for r in rows %}
  <tr><th>{{ r.label }}</th><td>{{ r.value }}</td></tr>
  {% endfor %}
</table>
{%- endmacro %}

{% macro entries(items) -%}
{% for item in items %}
  <h4>{{ item.title }}</h4>
  <p class="prose">{{ item.body }}</p>
{% endfor %}
{%- endmacro %}

{% macro photo(p) -%}
<figure>{% if p.src %}<img src="{{ p.src }}" alt="">{% else %}<div class="missing-image">Photograph unavailable</div>{% endif %}<figcaption>{{ p.caption }}</figcaption></figure>
{%- endmacro %}

{% macro signature(person, role) -%}
<div class="signature">
  <div class="sig-line"></div>
  {% if person %}
  <div class="sig-name">{{ person.name }}</div>
  <div class="sig-role">{{ role }}{% if person.title %} · {{ person.title }}{% endif %}</div>
  {% if person.qualifications %}<div>{{ person.qualifications }}</div>{% endif %}
  {% if person.rera_no %}<div>RERA registration no.: {{ person.rera_no }}</div>{% endif %}
  {% if person.rics_no %}<div>RICS membership no.: {{ person.rics_no }}</div>{% endif %}
  {% else %}
  <div class="sig-name missing">{{ role }} not assigned</div>
  {% endif %}
</div>
{%- endmacro %}

<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Valuation Report {{ meta.ref_no }}</title>
<style>{{ css }}</style>
</head>
<body class="{{ 'draft' if meta.is_draft else 'final' }}">

{# ---------- Cover ---------- #}
<section class="cover">
  <div class="logo">{{ firm.name }}</div>
  <h1>Valuation Report</h1>
  <p class="cover-address">{{ property.address or "—" }}</p>
  <table class="kv cover-table">
    <tr><th>Valuation Ref No.</th><td>{{ meta.ref_no }}{% if meta.version > 1 %} (version {{ meta.version }}){% endif %}</td></tr>
    <tr><th>Valuation date</th><td>{{ dates.valuation or "—" }}</td></tr>
    <tr><th>Prepared for</th><td>{{ client.name }}</td></tr>
    <tr><th>Prepared by</th><td>{{ firm.name }}</td></tr>
  </table>
  {% if meta.is_draft %}
  <div class="draft-box">
    <strong>DRAFT – not issued.</strong>
    {% if meta.outstanding %}
    <p>Still to complete before this can be sent for review:</p>
    <ul>{% for item in meta.outstanding %}<li>{{ item }}</li>{% endfor %}</ul>
    {% endif %}
  </div>
  {% endif %}
</section>

{# ---------- 1 Executive summary ---------- #}
<section>
  <h2>1. Executive Summary</h2>
  {% if exec_photos %}
  <div class="photo-row">{% for p in exec_photos %}{{ photo(p) }}{% endfor %}</div>
  {% elif meta.is_draft %}
  <p class="note">Executive-summary photographs have not been attached.</p>
  {% endif %}

  <h3>Property details</h3>
  {{ table(property_details) }}

  <h3>Valuation summary</h3>
  {{ table(valuation_summary) }}
  {% if bua_assumed_note %}<p class="note">{{ bua_assumed_note }}</p>{% endif %}

  {% if under_construction %}
  <h3>Under construction</h3>
  {{ table(under_construction) }}
  {% endif %}

  <div class="signatures">
    {{ signature(valuer, "Valuer") }}
    {{ signature(counter_signatory, "Counter-signatory") }}
  </div>
</section>

{# ---------- 2 Terms of engagement ---------- #}
<section>
  <h2>2. Terms of Engagement</h2>
  <h3>Addressee</h3>
  <p>{{ client.name }}{% if client.billing_address %}<br>{{ client.billing_address }}{% endif %}{% if client.po_box %}<br>PO Box {{ client.po_box }}{% endif %}</p>

  <h3>Reliance</h3>
  {{ placeholder("reliance and third-party reliance statement") }}

  <h3>Standards</h3>
  <p>This valuation has been prepared in accordance with the {{ standards }}.</p>

  <h3>Basis of value</h3>
  <p>The basis of value adopted is {{ valuation.basis or "—" }}.</p>
  {{ placeholder("definition of the basis of value, including highest and best use") }}

  <h3>Independence and objectivity</h3>
  {% if capacity %}<p>The valuer acted in the capacity of an {{ capacity | lower }} valuer.</p>{% endif %}
  {{ placeholder("statement of independence and objectivity") }}

  <h3>Disclosure</h3>
  <p class="prose">{{ text.disclosure or "—" }}</p>

  <h3>Knowledge and skills</h3>
  {{ placeholder("statement of the valuer's knowledge, skills and understanding") }}

  <h3>Assumptions</h3>
  {% if text.assumptions %}<p class="prose">{{ text.assumptions }}</p>{% else %}<p>None recorded.</p>{% endif %}

  <h3>Special assumptions</h3>
  {% if text.special_assumptions %}{{ entries(text.special_assumptions) }}{% else %}<p>None.</p>{% endif %}

  <h3>Other matters</h3>
  {% if text.other_matters %}{{ entries(text.other_matters) }}{% else %}<p>None.</p>{% endif %}
</section>

{# ---------- 3 Due diligence ---------- #}
<section>
  <h2>3. Extent of Due Diligence</h2>
  <p>{% if inspection_type %}An inspection of type “{{ inspection_type }}” was carried out{% if inspection_date %} on {{ inspection_date }}{% endif %}.{% else %}The type and date of inspection have not been recorded.{% endif %}</p>

  <h3>Information provided</h3>
  {% if information_provided %}<ul>{% for item in information_provided %}<li>{{ item }}</li>{% endfor %}</ul>{% else %}<p>None recorded.</p>{% endif %}

  <h3>Property areas</h3>
  <table class="grid">
    <tr><th>Item</th><th>Area</th><th>Source</th></tr>
    {% for r in areas %}
    <tr><td>{{ r.label }}</td><td>{{ r.value }}</td><td>{{ (bua_source if r.label == "Built-up area" else plot_source) or "—" }}</td></tr>
    {% endfor %}
  </table>
  {% if bua_assumed_note %}<p class="note">{{ bua_assumed_note }}</p>{% endif %}
</section>

{# ---------- 4 Property analysis ---------- #}
<section>
  <h2>4. Property Analysis</h2>
  <h3>Location</h3>
  {% if text.sub_community %}<p class="prose">{{ text.sub_community }}</p>{% endif %}
  {% if text.location %}<p class="prose">{{ text.location }}</p>{% endif %}
  {% if not (text.sub_community or text.location) %}<p>—</p>{% endif %}
  <div class="map-box">
    {% if property.coordinates %}Location map · {{ property.coordinates }}{% else %}Location map – coordinates not recorded{% endif %}
  </div>

  <h3>Description</h3>
  {% if text.specification %}<p class="prose">{{ text.specification }}</p>{% else %}<p>—</p>{% endif %}

  <h3>Accommodation</h3>
  <table class="grid">
    <tr><th>Floor</th><th>Accommodation</th></tr>
    <tr><td>{{ accommodation.floor or "—" }}</td><td>{{ accommodation.rooms | join(", ") or "—" }}</td></tr>
  </table>

  <h3>Building specification</h3>
  {% if building_specification %}{{ table(building_specification) }}{% else %}<p>—</p>{% endif %}

  {% if text.amenities %}<h3>Communal amenities</h3><p class="prose">{{ text.amenities }}</p>{% endif %}

  <h3>Condition</h3>
  {% if text.condition %}<p class="prose">{{ text.condition }}</p>{% else %}<p>—</p>{% endif %}
  {% if text.repairs %}<p class="prose"><strong>Repairs noted:</strong> {{ text.repairs }}</p>{% endif %}

  {% if reinstatement %}<h3>Reinstatement</h3><p>The estimated reinstatement value for insurance purposes is {{ reinstatement }}.</p>{% endif %}
</section>

{# ---------- 5 Market commentary ---------- #}
<section>
  <h2>5. Market Commentary</h2>
  {% if text.market_commentary %}<p class="prose">{{ text.market_commentary }}</p>{% else %}<p>—</p>{% endif %}
</section>

{# ---------- 6 Valuation methodology ---------- #}
<section>
  <h2>6. Valuation Methodology</h2>
  <p>The market approach, comparable method, has been used: the property is valued by reference to prices achieved for, or asked for, similar properties, adjusted for the differences between them and the subject.</p>
  {% if text.valuation_commentary %}<h3>Valuation commentary</h3><p class="prose">{{ text.valuation_commentary }}</p>{% endif %}

  <h3>Comparable evidence</h3>
  {% if comparables %}
  <table class="grid">
    <tr><th>District</th><th>Views</th><th>BUA (sqft)</th><th>Type</th><th>Net price (AED)</th><th>Transaction</th></tr>
    {% for c in comparables %}
    <tr><td>{{ c.district }}</td><td>{{ c.views }}</td><td>{{ c.bua_sqft }}</td><td>{{ c.type }}</td><td>{{ c.price }}</td><td>{{ c.transaction }}</td></tr>
    {% endfor %}
  </table>
  {% else %}
  <p class="note">No comparable evidence has been recorded for this valuation.</p>
  {% endif %}
</section>

{# ---------- 7 Opinion of market value ---------- #}
<section>
  <h2>7. Opinion of Market Value</h2>
  <p>Our opinion of the {{ valuation.basis or "value" }} of the property, as at {{ dates.valuation or "the valuation date" }}, is:</p>
  <div class="value-box">
    <div class="value-figure">{{ valuation.market_value or "—" }}</div>
    {% if valuation.market_value_words %}<div class="value-words">({{ valuation.market_value_words }})</div>{% endif %}
  </div>
  <p>This figure is stated gross of any costs of sale or purchase and takes no account of taxation.</p>
  {% if valuation.uncertainty %}
  <h3>Material valuation uncertainty</h3>
  {% if valuation.uncertainty_note %}<p class="prose">{{ valuation.uncertainty_note }}</p>{% endif %}
  {{ placeholder("standard material valuation uncertainty statement (RICS VPS 3 / VPGA 10)") }}
  {% endif %}
  <div class="signatures">
    {{ signature(valuer, "Valuer") }}
    {{ signature(counter_signatory, "Counter-signatory") }}
  </div>
</section>

{# ---------- 8 Disclaimer ---------- #}
<section>
  <h2>8. Disclaimer</h2>
  {{ placeholder("disclaimer") }}
</section>

{# ---------- Appendices ---------- #}
<section>
  <h2>Appendix 1 – Terms and Conditions</h2>
  {{ placeholder("terms and conditions of engagement") }}
</section>
<section>
  <h2>Appendix 2 – General Assumptions</h2>
  {{ placeholder("general assumptions") }}
</section>
<section>
  <h2>Appendix 3 – Bases of Valuation</h2>
  {{ placeholder("definitions of the bases of valuation") }}
</section>
<section>
  <h2>Appendix 4 – Documents Received</h2>
  {% if documents %}{% for d in documents %}
  <div class="document">
    <h4>{{ d.title }}{% if d.caption %} – {{ d.caption }}{% endif %}</h4>
    {% for src in d.pages %}
    <figure class="doc-page">{% if src %}<img src="{{ src }}" alt="">{% else %}<div class="missing-image">Page unavailable</div>{% endif %}<figcaption>Page {{ loop.index }} of {{ d.total_pages }}</figcaption></figure>
    {% else %}<figure><div class="missing-image">Document unavailable</div></figure>{% endfor %}
    {% if d.total_pages > d.pages|length and d.pages %}<p class="note">The first {{ d.pages|length }} of {{ d.total_pages }} pages are shown.</p>{% endif %}
  </div>
  {% endfor %}
  {% else %}<p class="note">No documents have been attached.</p>{% endif %}
</section>
<section>
  <h2>Appendix 5 – Inspection Photographs</h2>
  {% if photos %}<div class="photo-grid">{% for p in photos %}{{ photo(p) }}{% endfor %}</div>
  {% else %}<p class="note">No photographs have been attached.</p>{% endif %}
</section>

</body>
</html>

fields.css:
/* Standard valuation report. Placeholder branding until the final template
   arrives (CLAUDE.md §11): a text wordmark and a single accent colour. */

:root { --accent: #b3261e; --ink: #1f2933; --muted: #616e7c; --rule: #d9dee3; --wash: #f5f7f9; }

@page {
  size: A4;
  margin: 24mm 18mm 22mm 18mm;
  @top-left { content: "{{ firm_name | cssstr }}"; font: 600 9pt "Helvetica", sans-serif; color: var(--accent); }
  @bottom-left { content: "Valuation Ref No.: {{ ref_no | cssstr }}"; font: 8pt "Helvetica", sans-serif; color: var(--muted); }
  @bottom-right { content: "Page | " counter(page); font: 8pt "Helvetica", sans-serif; color: var(--muted); }
}
@page :first { @top-left { content: none; } }

/* A report is paper: white with dark ink whatever the viewer's theme. */
html { color-scheme: light; }
body { font: 10pt/1.5 "Helvetica", "Arial", sans-serif; color: var(--ink); margin: 0; }

{% if is_draft %}
/* Drawn as the page background so it repeats on every page of the PDF. */
@page {
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='210mm' height='297mm' viewBox='0 0 210 297'><text x='105' y='160' text-anchor='middle' font-family='Helvetica' font-weight='700' font-size='46' fill='%23b3261e' fill-opacity='0.07' transform='rotate(-30 105 160)'>DRAFT</text></svg>") no-repeat center / 210mm 297mm;
}
{% endif %}

/* On-screen preview only (WeasyPrint prints with @page): one A4 sheet wide. */
@media screen {
  html { background: #e9ecef; }
  body { background: #fff; max-width: 210mm; margin: 8mm auto; padding: 18mm; box-shadow: 0 1px 8px rgba(0, 0, 0, 0.15); box-sizing: border-box; }
  section { margin-bottom: 14mm; padding-bottom: 8mm; border-bottom: 1px dashed var(--rule); }
}
section { break-before: page; }
section.cover { break-before: auto; }

h1 { font-size: 30pt; margin: 40mm 0 6mm; letter-spacing: -0.5pt; }
h2 { font-size: 16pt; margin: 0 0 6mm; padding-bottom: 2mm; border-bottom: 2pt solid var(--accent); }
h3 { font-size: 11pt; margin: 6mm 0 2mm; color: var(--accent); }
h4 { font-size: 10pt; margin: 3mm 0 1mm; }
p { margin: 0 0 3mm; }
ul { margin: 0 0 3mm; padding-left: 5mm; }

.logo { font-size: 14pt; font-weight: 700; color: var(--accent); letter-spacing: 1pt; text-transform: uppercase; }
.cover-address { font-size: 14pt; margin-bottom: 10mm; }
.prose { white-space: pre-line; }
.note { color: var(--muted); font-style: italic; }
.placeholder { background: #fff3cd; border: 1pt dashed #b58105; padding: 2mm 3mm; color: #5c4400; font-size: 9pt; }
.missing { color: var(--accent); }

table { width: 100%; border-collapse: collapse; margin-bottom: 4mm; break-inside: auto; }
tr { break-inside: avoid; }
table.kv th { width: 38%; text-align: left; font-weight: 600; background: var(--wash); }
table.kv th, table.kv td { padding: 1.6mm 3mm; border-bottom: 0.5pt solid var(--rule); vertical-align: top; }
table.grid th { text-align: left; background: var(--wash); border-bottom: 1pt solid var(--ink); }
table.grid th, table.grid td { padding: 1.6mm 3mm; border-bottom: 0.5pt solid var(--rule); vertical-align: top; }
.cover-table { width: 70%; }

.value-box { border: 1.5pt solid var(--accent); padding: 6mm; margin: 4mm 0 5mm; text-align: center; }
.value-figure { font-size: 24pt; font-weight: 700; }
.value-words { color: var(--muted); margin-top: 1mm; }

.signatures { display: flex; gap: 12mm; margin-top: 14mm; break-inside: avoid; }
.signature { flex: 1; font-size: 9pt; }
.sig-line { border-bottom: 0.75pt solid var(--ink); height: 14mm; margin-bottom: 2mm; }
.sig-name { font-weight: 700; font-size: 10pt; }
.sig-role { color: var(--muted); }

.map-box { border: 1pt dashed var(--rule); background: var(--wash); height: 55mm; display: flex; align-items: center; justify-content: center; color: var(--muted); margin: 3mm 0; }

.photo-row, .photo-grid { display: grid; gap: 4mm; grid-template-columns: repeat(2, 1fr); }
.photo-row { grid-template-columns: repeat(3, 1fr); }
figure { margin: 0 0 4mm; break-inside: avoid; }
figure img { width: 100%; }
.document { margin-bottom: 6mm; }
.doc-page { text-align: center; }
/* Heading, page and caption have to fit on one A4 page, so a tall scan is limited by height, not width. */
.doc-page img { border: 0.5pt solid var(--rule); width: auto; max-width: 100%; max-height: 195mm; }
.document h4 { break-after: avoid; }
.missing-image { background: var(--wash); border: 0.5pt dashed var(--muted); color: var(--muted); padding: 12mm 4mm; text-align: center; font-size: 9pt; }
figcaption { font-size: 8.5pt; color: var(--muted); }

.draft-box { margin-top: 12mm; padding: 4mm; border: 1.5pt solid var(--accent); background: #fdecea; font-size: 9pt; }
